import{_ as e,o as t,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"人在回路与信任设计","description":"设计人工审批、复核、编辑、接管与升级机制，把风险、证据、权限、暂停恢复和运营能力连接起来。","frontmatter":{"title":"人在回路与信任设计","description":"设计人工审批、复核、编辑、接管与升级机制，把风险、证据、权限、暂停恢复和运营能力连接起来。","verified_at":"2026-07-31","source":["https://docs.langchain.com/oss/python/langgraph/interrupts","https://www.nist.gov/itl/ai-risk-management-framework","https://oecd.ai/en/ai-principles"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/architecture/technology-product-design/human-in-loop-trust-design.md","filePath":"py-agent/architecture/technology-product-design/human-in-loop-trust-design.md","lastUpdated":1786083160000}'),i={name:"py-agent/architecture/technology-product-design/human-in-loop-trust-design.md"};function l(s,a,o,h,p,d){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="人在回路与信任设计" tabindex="-1">人在回路与信任设计 <a class="header-anchor" href="#人在回路与信任设计" aria-label="Permalink to &quot;人在回路与信任设计&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>人在回路不是给每次模型输出加一个“确认”按钮。有效的人类监督要求：在正确风险点暂停，向有权限且有能力的人提供足够证据，允许真正修改或拒绝，并在恢复时保证不会重复副作用。</p><p>本章说明监督机制怎样进入系统设计；LangGraph 的 <code>interrupt()</code> 与恢复调用见<a href="/py-agent/workflow/durable-execution-recovery/interrupt-resume">Interrupt 与 Resume</a>，工具授权与 Sandbox 的纵深控制见<a href="/py-agent/quality/security-governance/tool-permissions-sandbox">工具权限与 Sandbox</a>。</p><h2 id="_1-人工角色" tabindex="-1">1. 人工角色 <a class="header-anchor" href="#_1-人工角色" aria-label="Permalink to &quot;1. 人工角色&quot;">​</a></h2><h3 id="_1-1-请求者" tabindex="-1">1.1 请求者 <a class="header-anchor" href="#_1-1-请求者" aria-label="Permalink to &quot;1.1 请求者&quot;">​</a></h3><p>发起任务并确认自己的高风险动作，未必具备专业复核资格。</p><h3 id="_1-2-审批者" tabindex="-1">1.2 审批者 <a class="header-anchor" href="#_1-2-审批者" aria-label="Permalink to &quot;1.2 审批者&quot;">​</a></h3><p>拥有对特定资源和动作的授权，如金额上限或数据访问。审批权来自身份系统，不来自模型指定。</p><h3 id="_1-3-领域评审者" tabindex="-1">1.3 领域评审者 <a class="header-anchor" href="#_1-3-领域评审者" aria-label="Permalink to &quot;1.3 领域评审者&quot;">​</a></h3><p>判断事实、政策或专业质量，可修改结果。其角色与安全审批可能不同。</p><h3 id="_1-4-运营人员" tabindex="-1">1.4 运营人员 <a class="header-anchor" href="#_1-4-运营人员" aria-label="Permalink to &quot;1.4 运营人员&quot;">​</a></h3><p>处理超时、队列、系统故障和批量异常，不一定有权查看完整敏感内容。</p><h3 id="_1-5-最终责任人" tabindex="-1">1.5 最终责任人 <a class="header-anchor" href="#_1-5-最终责任人" aria-label="Permalink to &quot;1.5 最终责任人&quot;">​</a></h3><p>对高影响结果负责并处理申诉。系统必须明确责任没有因使用 AI 自动转移给“模型”。</p><h2 id="_2-介入类型" tabindex="-1">2. 介入类型 <a class="header-anchor" href="#_2-介入类型" aria-label="Permalink to &quot;2. 介入类型&quot;">​</a></h2><h3 id="_2-1-approval" tabindex="-1">2.1 Approval <a class="header-anchor" href="#_2-1-approval" aria-label="Permalink to &quot;2.1 Approval&quot;">​</a></h3><p>在执行动作前批准/拒绝已固定参数。适合付款、发送、删除和权限变更。</p><h3 id="_2-2-review" tabindex="-1">2.2 Review <a class="header-anchor" href="#_2-2-review" aria-label="Permalink to &quot;2.2 Review&quot;">​</a></h3><p>检查输出、证据和政策符合性，可标记问题但不一定直接执行。</p><h3 id="_2-3-edit" tabindex="-1">2.3 Edit <a class="header-anchor" href="#_2-3-edit" aria-label="Permalink to &quot;2.3 Edit&quot;">​</a></h3><p>人修改草稿、工具参数或结构化计划。修改后重新运行受影响校验，不能沿用旧确认。</p><h3 id="_2-4-takeover" tabindex="-1">2.4 Takeover <a class="header-anchor" href="#_2-4-takeover" aria-label="Permalink to &quot;2.4 Takeover&quot;">​</a></h3><p>人接管后续对话或业务处理，Agent 停止自动行动并移交完整任务上下文。</p><h3 id="_2-5-escalation" tabindex="-1">2.5 Escalation <a class="header-anchor" href="#_2-5-escalation" aria-label="Permalink to &quot;2.5 Escalation&quot;">​</a></h3><p>按风险、冲突、证据不足、超预算或政策将任务升级到更高权限/专业角色。</p><h2 id="_3-介入位置" tabindex="-1">3. 介入位置 <a class="header-anchor" href="#_3-介入位置" aria-label="Permalink to &quot;3. 介入位置&quot;">​</a></h2><h3 id="_3-1-输入前" tabindex="-1">3.1 输入前 <a class="header-anchor" href="#_3-1-输入前" aria-label="Permalink to &quot;3.1 输入前&quot;">​</a></h3><p>确认数据用途、任务范围或自动化授权。适合批量或敏感数据处理。</p><h3 id="_3-2-计划后" tabindex="-1">3.2 计划后 <a class="header-anchor" href="#_3-2-计划后" aria-label="Permalink to &quot;3.2 计划后&quot;">​</a></h3><p>在执行前审查步骤、工具和资源范围。适合长任务和多动作计划，但计划仍可能在执行中变化，需要限制允许偏差。</p><h3 id="_3-3-高风险动作前" tabindex="-1">3.3 高风险动作前 <a class="header-anchor" href="#_3-3-高风险动作前" aria-label="Permalink to &quot;3.3 高风险动作前&quot;">​</a></h3><p>最重要的位置：模型已提出具体动作，执行尚未发生。确认绑定规范化参数和短期凭据。</p><h3 id="_3-4-结果后" tabindex="-1">3.4 结果后 <a class="header-anchor" href="#_3-4-结果后" aria-label="Permalink to &quot;3.4 结果后&quot;">​</a></h3><p>人工复核报告、代码或决定，再交付用户/下游。它不能撤回已经发生的工具副作用。</p><h3 id="_3-5-在线抽样" tabindex="-1">3.5 在线抽样 <a class="header-anchor" href="#_3-5-在线抽样" aria-label="Permalink to &quot;3.5 在线抽样&quot;">​</a></h3><p>对低风险自动结果抽样审计，发现漂移并回流评测。抽样不是高风险动作的替代控制。</p><h2 id="_4-触发策略" tabindex="-1">4. 触发策略 <a class="header-anchor" href="#_4-触发策略" aria-label="Permalink to &quot;4. 触发策略&quot;">​</a></h2><h3 id="_4-1-固定规则" tabindex="-1">4.1 固定规则 <a class="header-anchor" href="#_4-1-固定规则" aria-label="Permalink to &quot;4.1 固定规则&quot;">​</a></h3><p>金额、动作类型、数据分类、用户角色和政策命中由确定性规则触发，最可审计。</p><h3 id="_4-2-不确定性" tabindex="-1">4.2 不确定性 <a class="header-anchor" href="#_4-2-不确定性" aria-label="Permalink to &quot;4.2 不确定性&quot;">​</a></h3><p>证据缺失、来源冲突、多个候选或 Judge 分歧可触发人工。不要仅用模型自报置信度；应与可观察证据和校准数据结合。</p><h3 id="_4-3-异常行为" tabindex="-1">4.3 异常行为 <a class="header-anchor" href="#_4-3-异常行为" aria-label="Permalink to &quot;4.3 异常行为&quot;">​</a></h3><p>工具循环、参数频繁修改、跨域访问尝试、预算接近上限和历史分布外输入可触发暂停。</p><h3 id="_4-4-风险分层" tabindex="-1">4.4 风险分层 <a class="header-anchor" href="#_4-4-风险分层" aria-label="Permalink to &quot;4.4 风险分层&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>低风险 + 可逆 + 高可检测 -&gt; 自动执行 + 抽样</span></span>
<span class="line"><span>中风险或证据不足       -&gt; 人工复核</span></span>
<span class="line"><span>高风险或不可逆         -&gt; 执行前强审批</span></span>
<span class="line"><span>禁止行为               -&gt; 直接拒绝，不交给人工绕过</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="_5-审批信息包" tabindex="-1">5. 审批信息包 <a class="header-anchor" href="#_5-审批信息包" aria-label="Permalink to &quot;5. 审批信息包&quot;">​</a></h2><p>审批界面至少展示：</p><ul><li>任务目标和请求者；</li><li>规范化动作、对象、范围、金额/收件人；</li><li>使用的事实、来源和时间；</li><li>不确定、冲突和缺失信息；</li><li>策略命中与为何需要审批；</li><li>拒绝、修改、批准和升级的影响；</li><li>截止时间及已发生动作。</li></ul><p>模型长篇解释不是证据。默认折叠低价值内部 Trace，但允许授权人员查看来源和工具结果。</p><h2 id="_6-权限与确认令牌" tabindex="-1">6. 权限与确认令牌 <a class="header-anchor" href="#_6-权限与确认令牌" aria-label="Permalink to &quot;6. 权限与确认令牌&quot;">​</a></h2><p>审批者必须在服务端重新认证和授权。确认令牌绑定：主体、任务、动作、规范化参数哈希、权限范围、过期时间和一次性随机值。</p><p>参数、身份、政策版本或资源状态变化后令牌失效。模型和客户端不能自行设置 <code>approved=true</code> 作为最终依据。</p><p>职责分离可要求请求者不能审批自己的高风险动作，或超过阈值需双人批准。</p><h2 id="_7-暂停与恢复" tabindex="-1">7. 暂停与恢复 <a class="header-anchor" href="#_7-暂停与恢复" aria-label="Permalink to &quot;7. 暂停与恢复&quot;">​</a></h2><h3 id="_7-1-持久化" tabindex="-1">7.1 持久化 <a class="header-anchor" href="#_7-1-持久化" aria-label="Permalink to &quot;7.1 持久化&quot;">​</a></h3><p>在安全边界保存 Checkpoint、审批请求和业务 Task 状态。界面关闭、进程重启后仍可找到待办。</p><h3 id="_7-2-resume-输入" tabindex="-1">7.2 Resume 输入 <a class="header-anchor" href="#_7-2-resume-输入" aria-label="Permalink to &quot;7.2 Resume 输入&quot;">​</a></h3><p>恢复输入使用结构化决定：批准/拒绝/修改、审批者、令牌、时间和备注。不要把自然语言“可以”直接当成授权。</p><h3 id="_7-3-节点重放" tabindex="-1">7.3 节点重放 <a class="header-anchor" href="#_7-3-节点重放" aria-label="Permalink to &quot;7.3 节点重放&quot;">​</a></h3><p>LangGraph 等运行时恢复时可能从包含 Interrupt 的节点重新执行。Interrupt 之前的代码必须幂等，副作用尽量放在确认之后的独立节点。</p><h3 id="_7-4-超时与撤销" tabindex="-1">7.4 超时与撤销 <a class="header-anchor" href="#_7-4-超时与撤销" aria-label="Permalink to &quot;7.4 超时与撤销&quot;">​</a></h3><p>审批有过期时间；请求者和管理员可撤销。过期后转失败、重新规划或升级，不能永久占用运行资源。</p><h3 id="_7-5-完整控制链" tabindex="-1">7.5 完整控制链 <a class="header-anchor" href="#_7-5-完整控制链" aria-label="Permalink to &quot;7.5 完整控制链&quot;">​</a></h3><p>以“退款 120 元”为例，一次有效人工介入不是单独的按钮事件，而是下面这条可追踪序列：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent 提议动作</span></span>
<span class="line"><span>  -&gt; Policy 判定需要审批</span></span>
<span class="line"><span>  -&gt; 持久化业务任务与 Checkpoint</span></span>
<span class="line"><span>  -&gt; 创建审批请求并释放 Worker</span></span>
<span class="line"><span>  -&gt; 有权审批者查看证据并作出决定</span></span>
<span class="line"><span>  -&gt; 服务端重新校验身份、参数和业务状态</span></span>
<span class="line"><span>  -&gt; 使用结构化决定恢复 Workflow</span></span>
<span class="line"><span>  -&gt; 独立执行节点调用退款 API</span></span>
<span class="line"><span>  -&gt; 保存业务操作 ID、最终状态和审计事件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>关键记录如下：</p><table tabindex="0"><thead><tr><th>阶段</th><th>持久化事实</th><th>必须验证</th></tr></thead><tbody><tr><td>提议</td><td><code>order=A100</code>、<code>amount=120</code>、动作哈希、策略版本</td><td>参数已规范化，动作尚未执行</td></tr><tr><td>暂停</td><td><code>task=waiting_for_approval</code>、Checkpoint、审批请求 ID</td><td>Worker 已释放，重复通知幂等</td></tr><tr><td>决定</td><td>审批者、决定、一次性令牌、时间、备注</td><td>当前身份有权审批且未利益冲突</td></tr><tr><td>恢复</td><td>结构化 Resume 输入、最新订单版本</td><td>参数或业务状态变化时旧批准失效</td></tr><tr><td>执行</td><td>幂等键、退款 API 操作 ID、响应状态</td><td>结果不明时先查询，不重复退款</td></tr><tr><td>审计</td><td>提议、证据、审批、执行和最终用户通知</td><td>能从 Task 还原完整责任链</td></tr></tbody></table><p>若审批者把金额改为 100 元，系统创建新动作哈希并重新执行政策校验，原 120 元确认立即失效。若恢复节点重放，确认前的持久化可以重复，但退款调用只能位于确认后的独立、幂等执行节点。</p><h2 id="_8-人工工作队列" tabindex="-1">8. 人工工作队列 <a class="header-anchor" href="#_8-人工工作队列" aria-label="Permalink to &quot;8. 人工工作队列&quot;">​</a></h2><h3 id="_8-1-路由" tabindex="-1">8.1 路由 <a class="header-anchor" href="#_8-1-路由" aria-label="Permalink to &quot;8.1 路由&quot;">​</a></h3><p>按领域、权限、语言、租户、严重度和利益冲突分配。任务状态和所有权用权威数据库管理。</p><h3 id="_8-2-sla" tabindex="-1">8.2 SLA <a class="header-anchor" href="#_8-2-sla" aria-label="Permalink to &quot;8.2 SLA&quot;">​</a></h3><p>定义接单/完成时间、超时升级和非工作时间策略。若人工能力不足，系统不能假装“人在回路”可无限扩展。</p><h3 id="_8-3-并发" tabindex="-1">8.3 并发 <a class="header-anchor" href="#_8-3-并发" aria-label="Permalink to &quot;8.3 并发&quot;">​</a></h3><p>同一审批只允许一个有效决定，使用版本或条件更新处理多人同时操作。修改后让旧页面审批应失败。</p><h3 id="_8-4-隐私" tabindex="-1">8.4 隐私 <a class="header-anchor" href="#_8-4-隐私" aria-label="Permalink to &quot;8.4 隐私&quot;">​</a></h3><p>评审者只看完成职责所需数据；高敏字段按角色遮蔽，访问进入审计。</p><h2 id="_9-防止橡皮图章" tabindex="-1">9. 防止橡皮图章 <a class="header-anchor" href="#_9-防止橡皮图章" aria-label="Permalink to &quot;9. 防止橡皮图章&quot;">​</a></h2><ul><li>只在真正需要时请求确认；</li><li>把关键动作和变化突出显示；</li><li>提供证据与反例，而非默认只突出“批准”；</li><li>拒绝和修改操作同样容易；</li><li>对高风险批量审批设置数量与节奏限制；</li><li>抽检审批质量并反馈培训；</li><li>不以“审批速度”作为唯一绩效指标。</li></ul><p>若批准率接近 100%，可能是 Agent 很准，也可能是流程没有真实监督，需要抽样核验。</p><h2 id="_10-信任校准" tabindex="-1">10. 信任校准 <a class="header-anchor" href="#_10-信任校准" aria-label="Permalink to &quot;10. 信任校准&quot;">​</a></h2><p>界面说明系统的能力、限制、数据和人工角色。展示实际来源、工具结果与业务状态，不展示虚构的“模型思维过程”。</p><p>避免过度信任，也避免无差别警告导致用户忽略。风险信息与当前决定相关，并提供明确动作。</p><h2 id="_11-评测与运营指标" tabindex="-1">11. 评测与运营指标 <a class="header-anchor" href="#_11-评测与运营指标" aria-label="Permalink to &quot;11. 评测与运营指标&quot;">​</a></h2><p>测人工介入率、等待时间、批准/拒绝/修改、Agent 与人工一致性、审批后事故、漏升级、无效升级、重复动作和每成功任务人工成本。按任务与风险 Slice 分析。</p><p>用历史决定建立触发策略时防止自动复制人类偏差。高风险政策变化后重新校准，并保留申诉和专家仲裁。</p><h2 id="_12-常见误区" tabindex="-1">12. 常见误区 <a class="header-anchor" href="#_12-常见误区" aria-label="Permalink to &quot;12. 常见误区&quot;">​</a></h2><ol><li><strong>有确认按钮就有人监督</strong>：审批者可能无证据、权限或时间。</li><li><strong>模型低置信才人工</strong>：自报置信度可能未校准。</li><li><strong>审批后可随意改参数</strong>：确认必须绑定具体动作。</li><li><strong>Interrupt 自动保证副作用安全</strong>：节点重放仍需幂等设计。</li><li><strong>人工容量无限</strong>：积压会让 SLO 和控制同时失效。</li></ol><h2 id="_13-验收清单" tabindex="-1">13. 验收清单 <a class="header-anchor" href="#_13-验收清单" aria-label="Permalink to &quot;13. 验收清单&quot;">​</a></h2><ul><li>人工角色、权限和最终责任是否明确；</li><li>介入点是否位于风险发生前的有效位置；</li><li>触发是否结合确定规则、证据和校准信号；</li><li>审批信息是否足以判断且最小披露；</li><li>确认是否绑定主体、参数、范围、版本和有效期；</li><li>暂停、重放、超时、撤销和并发是否有明确语义；</li><li>人工队列容量与 SLA 是否真实可运行；</li><li>是否评测漏升级、审批事故和橡皮图章行为。</li></ul><p>人在回路的价值不是把风险推给用户或员工，而是把人类判断放在真正能改变结果的控制点，并用权限、证据和恢复机制保证这个判断有效。</p>`,92)])])}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
